using System;
using System.Collections.Generic;
using System.Linq;

public class StringCounter
{
    /// <summary>
    /// Counts the occurrences of nonempty strings from an IEnumerable<string?> using ordinal case-insensitive comparison.
    /// </summary>
    /// <param name="input">The enumerable of nullable strings to process.</param>
    /// <returns>A Dictionary where keys are the unique, lowercased, non-empty strings and values are their counts.</returns>
    public Dictionary<string, int> CountNonEmptyStrings(IEnumerable<string?> input)
    {
        if (input == null)
        {
            return new Dictionary<string, int>();
        }

        var counts = new Dictionary<string, int>();

        foreach (var str in input)
        {
            // 1. Ignore null elements
            if (str == null)
            {
                continue;
            }

            // 2. Ignore empty elements
            if (string.IsNullOrWhiteSpace(str))
            {
                continue;
            }

            // 3. Perform case-insensitive comparison (by converting to lower case)
            string key = str.ToLowerInvariant();

            // Update the count
            if (counts.ContainsKey(key))
            {
                counts[key]++;
            }
            else
            {
                counts.Add(key, 1);
            }
        }

        return counts;
    }
}

